// src/pages/CustomerCare.jsx
import React, { useState } from 'react';
import { useAuth } from '../hooks/useAuth.js';
import { useClaim } from '../hooks/useClaim.js';
import { useAutoDismiss } from '../hooks/useTimer.js';
import SearchBar from '../components/common/SearchBar.jsx';
import ClaimCard from '../components/common/ClaimCard.jsx';
import EmptyState from '../components/common/EmptyState.jsx';
import ToggleGroup from '../components/common/ToggleGroup.jsx';
import TransactionForm from '../components/common/TransactionForm.jsx';
import RoleNav from '../components/navigation/RoleNav.jsx';
import { STEP_TYPES } from '../constants/roles.js';
import { CLAIM_STATUS, CLAIM_TYPE, CLAIM_SUBTYPE } from '../constants/claimStatus.js';
import './CustomerCare.css';

const CustomerCare = () => {
  const { user } = useAuth();
  const { 
    currentClaim, 
    fetchClaim, 
    setCurrentClaim, 
    isLoading, 
    updateClaim,
    completeTransaction,
    claims 
  } = useClaim();
  
  const [searchValue, setSearchValue] = useState('255685968876');
  const [step, setStep] = useState(STEP_TYPES.SEARCH);
  const [selectedOption, setSelectedOption] = useState(null);
  const [selectedType, setSelectedType] = useState(null);

  const [txData, setTxData] = useState({
    primaryAmount: '',
    primaryTxId: '',
    excessAmount: '',
    excessTxId: '',
    date: new Date().toLocaleDateString(),
    rep: user?.name || 'Shabani'
  });

  // Use auto-dismiss hook for popup
  const { 
    isVisible: isPopupVisible, 
    show: showPopup, 
    dismiss: dismissPopup,
    progress: popupProgress 
  } = useAutoDismiss(4000, () => {
    // When popup auto-dismisses, close it
  });

  // Same search logic as Representative - fetches from shared API
  const handleSearch = async () => {
    if (!searchValue.trim()) return;
    try {
      // Check if claim already exists in our claims
      let existingClaim = claims.find(c => c.msisdn === searchValue.trim());
      
      if (existingClaim) {
        setCurrentClaim(existingClaim);
        setStep(STEP_TYPES.DETAILS);
        return;
      }

      // If not found, fetch from API (same shared API)
      const data = await fetchClaim(searchValue.trim());
      if (data) {
        // Initialize claim with representative
        const newClaim = {
          ...data,
          representative: user?.name || 'Shabani',
          status: CLAIM_STATUS.PENDING
        };
        setCurrentClaim(newClaim);
        setStep(STEP_TYPES.DETAILS);
      }
    } catch (error) {
      alert('Error fetching claim: ' + error.message);
    }
  };

  const handleAddPayment = () => {
    // For Customer Care, only Repair option is available
    setSelectedOption(CLAIM_TYPE.REPAIR);
    showPopup();
  };

  const handleOptionSelect = (option) => {
    dismissPopup();
    setSelectedOption(option);
    setStep(STEP_TYPES.TOGGLE);
  };

  const handleTypeSelect = (type) => {
    setSelectedType(type);
    
    // Update claim with type and subtype
    if (currentClaim) {
      updateClaim(currentClaim.id, {
        claim_type: CLAIM_TYPE.REPAIR,
        claim_subtype: type,
        representative: user?.name || 'Shabani'
      });
    }

    // Go to transaction form
    setStep(STEP_TYPES.TRANSACTION);
  };

  const handleTxChange = (e) => {
    const { name, value } = e.target;
    setTxData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmitTx = () => {
    // For Repair with Excess
    if (selectedType === CLAIM_SUBTYPE.EXCESS) {
      if (!txData.primaryTxId) {
        alert('Please enter the base repair transaction ID');
        return;
      }
      if (!txData.primaryAmount) {
        alert('Please enter the base repair amount');
        return;
      }
      if (!txData.excessTxId) {
        alert('Please enter the excess fee transaction ID');
        return;
      }
      if (!txData.excessAmount) {
        alert('Please enter the excess fee amount');
        return;
      }

      // Complete the transaction with both IDs
      if (currentClaim) {
        completeTransaction(currentClaim.id, {
          primaryTxId: txData.primaryTxId,
          primaryAmount: parseFloat(txData.primaryAmount),
          excessTxId: txData.excessTxId,
          excessAmount: parseFloat(txData.excessAmount),
          date: txData.date,
          screenshot: null,
          isExcess: true
        });
      }
    } 
    // For Normal Repair
    else {
      if (!txData.primaryTxId) {
        alert('Please enter a transaction ID');
        return;
      }
      if (!txData.primaryAmount) {
        alert('Please enter the transaction amount');
        return;
      }

      if (currentClaim) {
        completeTransaction(currentClaim.id, {
          primaryTxId: txData.primaryTxId,
          primaryAmount: parseFloat(txData.primaryAmount),
          date: txData.date,
          screenshot: null,
          isExcess: false
        });
      }
    }

    alert('✅ Repair claim submitted for verification!');
    resetFlow();
  };

  const handleCancel = () => {
    resetFlow();
  };

  const resetFlow = () => {
    setStep(STEP_TYPES.SEARCH);
    setCurrentClaim(null);
    setSelectedOption(null);
    setSelectedType(null);
    setTxData({
      primaryAmount: '',
      primaryTxId: '',
      excessAmount: '',
      excessTxId: '',
      date: new Date().toLocaleDateString(),
      rep: user?.name || 'Shabani'
    });
    dismissPopup();
  };

  const renderContent = () => {
    switch (step) {
      case STEP_TYPES.SEARCH:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <EmptyState 
              icon="fa-search"
              title="No claim loaded"
              description="Search for a claim using phone number"
            />
          </>
        );
      
      case STEP_TYPES.DETAILS:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <ClaimCard 
              claim={currentClaim}
              representative={user?.name || 'Shabani'}
              onAddPayment={handleAddPayment}
              onOptionSelect={handleOptionSelect}
              popupVisible={isPopupVisible}
              popupProgress={popupProgress}
              isCare={true}
            />
          </>
        );
      
      case STEP_TYPES.TOGGLE:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <ToggleGroup 
              selected={selectedType}
              onSelect={handleTypeSelect}
              title="Repair Type"
            />
          </>
        );
      
      case STEP_TYPES.TRANSACTION:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <TransactionForm 
              title={`Repair · ${selectedType}`}
              isReplacement={false}
              isExcess={selectedType === CLAIM_SUBTYPE.EXCESS}
              txData={txData}
              onChange={handleTxChange}
              onSubmit={handleSubmitTx}
              onCancel={handleCancel}
              representative={user?.name || 'Shabani'}
              isPending={false}
              isCare={true}
            />
          </>
        );
      
      default:
        return null;
    }
  };

  return (
    <div className="care-page">
      <div className="care-header">
        <div className="care-header-content">
          <i className="fas fa-hand-holding-heart"></i>
          <h2>Repair Management <span className="subtitle">Customer Care</span></h2>
        </div>
        <div className="care-badge">
          <i className="fas fa-tools"></i> Repair Only
        </div>
      </div>
      
      <RoleNav activeRole="care" onRoleChange={() => {}} />
      
      <div className="care-content step-transition">
        {renderContent()}
      </div>
    </div>
  );
};

export default CustomerCare;
